fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut mask: i32 = host::display::state_get(0);
    let mut cnt: i32 = 0;
    let mut i: i32 = 0;
    while i < 4 {
        if ((mask >> i) & 1) == 1 { cnt = cnt + 1; }
        i = i + 1;
    }
    if down == 1 && prev == 0 && px >= 40 && px < 260 {
        if py >= 40 && py < 66 {
            if cnt == 4 { mask = 0; } else { mask = 15; }
        }
        let mut k: i32 = 0;
        while k < 4 {
            let y: i32 = 90 + k * 36;
            if py >= y && py < y + 26 { mask = mask ^ (1 << k); }
            k = k + 1;
        }
        host::display::state_set(0, mask);
    }
    host::display::state_set(1, down);
    cnt = 0;
    i = 0;
    while i < 4 {
        if ((mask >> i) & 1) == 1 { cnt = cnt + 1; }
        i = i + 1;
    }
    host::display::clear(0x101014);
    host::display::fill_rect(40, 40, 22, 22, 0x404040);
    host::display::fill_rect(43, 43, 16, 16, 0x101014);
    if cnt == 4 { host::display::fill_rect(46, 46, 10, 10, 0x00ff88); }
    if cnt > 0 && cnt < 4 { host::display::fill_rect(45, 49, 12, 4, 0x808080); }
    host::display::draw_string(74, 46, "SELECT ALL", 0xffffff, 1);
    i = 0;
    while i < 4 {
        let y: i32 = 90 + i * 36;
        host::display::fill_rect(40, y, 22, 22, 0x404040);
        host::display::fill_rect(43, y + 3, 16, 16, 0x101014);
        if ((mask >> i) & 1) == 1 {
            host::display::fill_rect(46, y + 6, 10, 10, 0x00ff88);
        }
        i = i + 1;
    }
    host::display::draw_string(74, 96, "ALPHA", 0xffffff, 1);
    host::display::draw_string(74, 132, "BRAVO", 0xffffff, 1);
    host::display::draw_string(74, 168, "CHARLIE", 0xffffff, 1);
    host::display::draw_string(74, 204, "DELTA", 0xffffff, 1);
    host::display::draw_number(40, 250, cnt, 0xffffff, 2);
    host::display::draw_string(70, 250, "OF 4", 0x808080, 2);
    host::display::present();
}
